INSERT INTO sys_window (sys_window_id, name, description, help, icon, window_type, is_sales_transaction, is_default, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('d4aff293-b99f-5a16-a201-b2e56dca96a6', 'City', 'Maintain City records', 'Create, find and maintain City records. The list shows every City you have access to — select a row to open it, or use New to add one. Each row is a single City, described by 10 fields.

Id and Code are unique: no two City records may share the same value, and a save that would duplicate one is rejected. Code, Name and Country must be filled in before the record can be saved.

Every City points at Country and State Province. Choose the linked record from the lookup on those fields rather than typing an identifier. Address refers back to City, so what you change here can affect that record.

Every save starts as a Draft. The business rules and workflows attached to City then run together in a single transaction: if all of them succeed the record becomes Final; if any of them fails, nothing they changed is kept — the record stays Draft and the reason is written onto it so you can fix the cause and retry. A City with no rules or workflows attached is marked Final immediately.', 'building-2', 'M', FALSE, TRUE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_table (sys_table_id, table_name, name, description, icon, access_level, is_view, is_document, is_high_volume, is_changelog, sys_window_id, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('0ebeefb6-012f-544a-8d9f-12810c11acb5', 'bus_city', 'City', 'Loaded from the GeoNames reference data rather than typed by users; chosen on addresses, locations and offices, and read to sort, filter and map records by place. A city: every national capital and every city of 750 thousand or more, from GeoNames, linked to its country and, for the United States and Canada, to its state or province. A city: every national capital and every city of 750 thousand or more, from GeoNames, linked to its country and, for the United States and Canada, to its state or province. Chosen from the list wherever a record needs a place, code or currency; maintained by an administrator when a registry changes.', 'building-2', 'A', FALSE, FALSE, FALSE, TRUE, 'd4aff293-b99f-5a16-a201-b2e56dca96a6', 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_tab (sys_tab_id, sys_window_id, sys_table_id, name, help, tab_level, seq_no, is_single_row, has_tree, is_info_tab, is_translation_tab, is_read_only, is_insert_record, is_advanced_tab, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('0754a372-d1fa-5d99-a386-c2ca31b19db1', 'd4aff293-b99f-5a16-a201-b2e56dca96a6', '0ebeefb6-012f-544a-8d9f-12810c11acb5', 'City', 'Shows one City at a time. Fields are grouped: General carries the identifying fields and Details carries the rest. 3 fields marked with a red asterisk (*) must have a value before Save will accept the record. Country and State Province are lookups — search the linked records instead of entering an identifier by hand. Any field showing a ? beside its label has help of its own; click it for the rules that apply there.', 0, 10, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
