VALUES ('373f2955-539e-5260-a392-a1dbef67100c', '2144d91a-015b-56e1-9ab7-e6843a6d35ac', '3b2f4b4f-0237-5ea3-b991-c30be27640a5', 'a0e97de9-979a-56f6-af50-deacd5e8ff17', 'Started At', 'Set when work starts. Not later than the completion time. Records when the started event occurred. It establishes chronology, supports auditability, and helps coordinate related lifecycle and process activities.', 90, 90, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
