INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('92fb685b-cb11-5070-ba2a-2d3e24e04143', '97f01bc2-b81d-5cc5-82b1-d2548ac3c496', '73e81532-648b-5575-9224-dc6dd3f080fe', 'c715c55a-6571-5977-bf6a-8b53827d96cd', 'Id', 'Stable identity of one characteristic configuration within a QualityPlan. Identifies the specific plan-level requirement that governs how one QualityCharacteristic is inspected. Traceability, configuration, inspection execution, audit, and integration. Links one QualityPlan to one reusable QualityCharacteristic and its plan-specific criteria. Must be unique: a save is rejected if another Quality Plan Characteristic already uses this value.', 10, 10, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('331fc244-6884-5324-822f-e5868c6a4397', '97f01bc2-b81d-5cc5-82b1-d2548ac3c496', '208cb724-85bb-5d8a-ab55-214642c9dd47', 'c715c55a-6571-5977-bf6a-8b53827d96cd', 'Sequence Number', 'Execution or presentation order of this quality characteristic within the plan. Determines where the characteristic appears in inspection instructions and can support ordered sampling or testing. Inspection forms, operator guidance, reports, and workflow orchestration. Sequence is scoped to the QualityPlan and does not change the reusable characteristic''s identity. Required — the record cannot be saved while this is empty.', 20, 20, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('6ea1d45a-dc60-5c84-a8d3-65ab8f70e820', '97f01bc2-b81d-5cc5-82b1-d2548ac3c496', 'ac3cbfa1-7d35-5be5-8007-1ffbdaa72ee8', 'c715c55a-6571-5977-bf6a-8b53827d96cd', 'Required', 'Indicates whether evidence for this characteristic is mandatory for the governing plan. Determines whether the absence of a measurement can prevent inspection completion. Inspection validation, completion gating, audit, and exception handling. QualityInspection uses this setting when determining whether all required measurements have been evaluated. Required — the record cannot be saved while this is empty.', 30, 30, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('7a8a49fd-a05f-55da-b100-c068df514f8c', '97f01bc2-b81d-5cc5-82b1-d2548ac3c496', 'a30a12e8-4a82-572d-b8c7-1eb5abd0f229', 'a0e97de9-979a-56f6-af50-deacd5e8ff17', 'Lower Limit', 'The smallest numeric measurement this plan accepts for the characteristic; anything below it fails. Set by quality engineers when authoring the plan; compared with each measurement during inspection review and must not exceed the upper limit. Defines the minimum acceptable value under this particular QualityPlan. Applies only to the linked QualityCharacteristic in this plan and must use a compatible unit.', 40, 40, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('cb8ea3db-443d-50c3-8a51-eb7335a25b9f', '97f01bc2-b81d-5cc5-82b1-d2548ac3c496', '31c9ea81-7327-5f11-ba28-1d456eb276b9', 'a0e97de9-979a-56f6-af50-deacd5e8ff17', 'Upper Limit', 'The largest numeric measurement this plan accepts for the characteristic; anything above it fails. Set by quality engineers when authoring the plan; compared with each measurement during inspection review and must not fall below the lower limit. Defines the maximum acceptable value under this particular QualityPlan. Applies only to the linked QualityCharacteristic in this plan and must use a compatible unit.', 50, 50, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('bbf15f96-eb01-5277-b588-7fffdbdabeff', '97f01bc2-b81d-5cc5-82b1-d2548ac3c496', '3cd8199b-7a43-57d1-adba-31d2f8ab256c', 'a0e97de9-979a-56f6-af50-deacd5e8ff17', 'Target Value', 'Preferred numeric target for the characteristic under this plan. Represents the desired value rather than the minimum or maximum acceptance boundary. Process optimization, inspection guidance, analytics, and trend analysis. Must be compatible with the characteristic data type and acceptance limits.', 60, 60, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
