-- --------------------------------------------------------------------------
-- Test Method (bus_test_method)
-- --------------------------------------------------------------------------
INSERT INTO sys_window (sys_window_id, name, description, help, icon, window_type, is_sales_transaction, is_default, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('c2fc5cd3-a2b9-5fe6-911c-31920e72f516', 'Test Method', 'Maintain Test Method records', 'Create, find and maintain Test Method records. The list shows every Test Method you have access to — select a row to open it, or use New to add one. Each row is a single Test Method, described by 5 fields.

Id and Code are unique: no two Test Method records may share the same value, and a save that would duplicate one is rejected. Code, Name and Status must be filled in before the record can be saved.

Quality Plan Characteristic and Quality Measurement refer back to Test Method, so what you change here can affect those records.

Every save starts as a Draft. The business rules and workflows attached to Test Method then run together in a single transaction: if all of them succeed the record becomes Final; if any of them fails, nothing they changed is kept — the record stays Draft and the reason is written onto it so you can fix the cause and retry. A Test Method with no rules or workflows attached is marked Final immediately.', 'flask-conical', 'M', FALSE, TRUE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_table (sys_table_id, table_name, name, description, icon, access_level, is_view, is_document, is_high_volume, is_changelog, sys_window_id, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('d07e8a22-030a-534a-abcc-cc88afb4f3a9', 'bus_test_method', 'Test Method', 'Reusable governed procedure for producing quality evidence. TestMethod separates how an observation is produced from what QualityCharacteristic is observed and what QualityPlanCharacteristic criteria apply. Quality planning, laboratory testing, incoming inspection, compliance, training, audit, and analytics. QualityPlanCharacteristic selects the method; QualityMeasurement records evidence produced under it. Draft → active → suspended/retired under controlled change. Method lifecycle or semantic changes revalidate affected open configurations and inspections while completed evidence remains historically stable.', 'flask-conical', 'A', FALSE, FALSE, FALSE, TRUE, 'c2fc5cd3-a2b9-5fe6-911c-31920e72f516', 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_tab (sys_tab_id, sys_window_id, sys_table_id, name, help, tab_level, seq_no, is_single_row, has_tree, is_info_tab, is_translation_tab, is_read_only, is_insert_record, is_advanced_tab, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('c85c8622-f421-5fc5-98d9-95af9be2c369', 'c2fc5cd3-a2b9-5fe6-911c-31920e72f516', 'd07e8a22-030a-534a-abcc-cc88afb4f3a9', 'Test Method', 'Shows one Test Method at a time. Fields are grouped: General carries the identifying fields and Details carries the rest. 3 fields marked with a red asterisk (*) must have a value before Save will accept the record. Any field showing a ? beside its label has help of its own; click it for the rules that apply there.', 0, 10, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('62fdf862-9d81-550f-8f6f-fcbd2c0feec7', 'd07e8a22-030a-534a-abcc-cc88afb4f3a9', 'id', 'Id', 'Stable identity of the governed test method. Identifies one reusable procedure independently of plans and measurements. Quality planning, laboratory execution, audit, and integration. Referenced by quality configurations and test evidence.', 13, NULL, NULL, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, FALSE, FALSE, TRUE, FALSE, 10, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('77a2bae1-7545-5030-9bf0-3f06b33ae81a', 'd07e8a22-030a-534a-abcc-cc88afb4f3a9', 'code', 'Code', 'The controlled business code identifying the test method, such as TM-HPLC-012. Assigned when the method is authored; unique, and quoted on inspection plans, results and laboratory records to show which procedure was used. Human-readable controlled identifier for the procedure. Remains stable within its governed version.', 10, 100, NULL, FALSE, FALSE, TRUE, TRUE, TRUE, TRUE, FALSE, FALSE, TRUE, TRUE, 20, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('6b00b858-284b-5eae-a12a-4f7b6b50fd6c', 'd07e8a22-030a-534a-abcc-cc88afb4f3a9', 'name', 'Name', 'The readable name of the test method as quality and laboratory staff know it. Entered by method owners; shown when planning inspections and recording results. States the procedure understood by quality and laboratory personnel. Complements the controlled code.', 10, 300, NULL, FALSE, FALSE, TRUE, TRUE, TRUE, TRUE, FALSE, FALSE, TRUE, TRUE, 30, 'U', TRUE, 'system', 'system', NOW(), NOW())
