-- --------------------------------------------------------------------------
-- Quality Measurement (bus_quality_measurement)
-- --------------------------------------------------------------------------
INSERT INTO sys_window (sys_window_id, name, description, help, icon, window_type, is_sales_transaction, is_default, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('1ed2a7c5-5557-5e23-a04f-f8abd24211a6', 'Quality Measurement', 'Maintain Quality Measurement records', 'Create, find and maintain Quality Measurement records. The list shows every Quality Measurement you have access to — select a row to open it, or use New to add one. Each row is a single Quality Measurement, described by 19 fields.

Id and Measurement Number are unique: no two Quality Measurement records may share the same value, and a save that would duplicate one is rejected. Measurement Number, Characteristic Code, Result, Measured At and Quality Inspection must be filled in before the record can be saved.

Every Quality Measurement points at Quality Characteristic, Quality Plan Characteristic, Test Method, Quality Inspection, Inspection Sample, Quality Plan and Certificate Of Analysis. Choose the linked record from the lookup on those fields rather than typing an identifier.

Every save starts as a Draft. The business rules and workflows attached to Quality Measurement then run together in a single transaction: if all of them succeed the record becomes Final; if any of them fails, nothing they changed is kept — the record stays Draft and the reason is written onto it so you can fix the cause and retry. A Quality Measurement with no rules or workflows attached is marked Final immediately.', 'badge-check', 'M', FALSE, TRUE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_table (sys_table_id, table_name, name, description, icon, access_level, is_view, is_document, is_high_volume, is_changelog, sys_window_id, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('ca3370d1-6356-5045-a4b5-2511ba99efcf', 'bus_quality_measurement', 'Quality Measurement', 'Structured auditable evidence for one quality characteristic observed during a QualityInspection. QualityMeasurement separates the factual observation from the inspection-level conclusion while retaining the exact plan configuration used for evaluation. Incoming inspection, supplier quality, laboratory testing, dimensional checks, sampling, process quality, compliance, nonconformance and corrective-action verification. QualityInspection is the execution context; InspectionSample supplies exact sample provenance when sampling applies; QualityPlanCharacteristic supplies authoritative plan-specific requirements; QualityCharacteristic supplies reusable meaning; QualityPlan supplies the parent definition; Product identifies material; UnitOfMeasure supplies dimensional semantics; Nonconformance may consume failed evidence. QualityPlan → QualityPlanCharacteristic → SamplingPlan/SamplingRule where required → QualityInspection → InspectionSample where required → measurement capture → validate characteristic/unit/method → evaluate against configured criteria → measurement result → aggregate inspection result → Nonconformance/disposition where required. Captured → evaluated → retained as completed inspection evidence; corrections use explicit amendment or remeasurement. Changes to governing plan characteristics, reusable characteristics, product or unit definitions affect open measurements and trigger revalidation. Completed measurements retain the configuration snapshots applicable when captured. A receiving plan configures WEIGHT at 9.8–10.2 KG. A QualityMeasurement records 10.35 KG, links to the governing QualityPlanCharacteristic and QualityCharacteristic, snapshots the applicable limits, and evaluates to FAIL.', 'badge-check', 'A', FALSE, FALSE, FALSE, TRUE, '1ed2a7c5-5557-5e23-a04f-f8abd24211a6', 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_tab (sys_tab_id, sys_window_id, sys_table_id, name, help, tab_level, seq_no, is_single_row, has_tree, is_info_tab, is_translation_tab, is_read_only, is_insert_record, is_advanced_tab, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('7129094f-6a92-567d-82ca-cfd9be683e5d', '1ed2a7c5-5557-5e23-a04f-f8abd24211a6', 'ca3370d1-6356-5045-a4b5-2511ba99efcf', 'Quality Measurement', 'Shows one Quality Measurement at a time. Fields are grouped: General carries the identifying fields and Details carries the rest. 5 fields marked with a red asterisk (*) must have a value before Save will accept the record. Quality Characteristic, Quality Plan Characteristic, Test Method, Quality Inspection, Inspection Sample, Quality Plan and Certificate Of Analysis are lookups — search the linked records instead of entering an identifier by hand. Any field showing a ? beside its label has help of its own; click it for the rules that apply there.', 0, 10, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('cc18fce5-d6ad-5cdc-8bfb-68bfee2370eb', 'ca3370d1-6356-5045-a4b5-2511ba99efcf', 'id', 'Id', 'The permanent, system-generated identity of this single quality observation. Generated on creation and never changed; traceability, audits, analytics and integrations refer to the measurement through it. Identifies one observation independently of its inspection and characteristic. Distinct from QualityInspection and the measured Product. Stable reference from capture through review.', 13, NULL, NULL, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, FALSE, FALSE, TRUE, FALSE, 10, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('da451262-5afb-53c8-8595-c0fec6800638', 'ca3370d1-6356-5045-a4b5-2511ba99efcf', 'measurement_number', 'Measurement Number', 'The human-facing reference that identifies this one measurement within inspection records. Assigned when the measurement is captured and unique; used by reviewers, auditors and integrations to cite it. Provides an operational identifier for one observation. Distinct from the parent inspection number. Supports individual observation traceability.', 10, 100, NULL, FALSE, FALSE, TRUE, TRUE, TRUE, TRUE, FALSE, FALSE, TRUE, TRUE, 20, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('342ff7ba-453b-58e8-903a-4d1853bc987b', 'ca3370d1-6356-5045-a4b5-2511ba99efcf', 'characteristic_code', 'Characteristic Code', 'Snapshot of the quality characteristic business code evaluated by this observation. Preserves the human-readable characteristic identifier applicable when evidence was captured. Audit, reporting, exports and legacy integration. Must correspond to the linked QualityCharacteristic through QualityPlanCharacteristic and must not be treated as the authoritative configuration key. Provides readable historical context while the relationship graph supplies authoritative semantics.', 10, 100, NULL, FALSE, FALSE, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 30, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('17f4f8e9-b3f1-52f2-94ab-86a65245729a', 'ca3370d1-6356-5045-a4b5-2511ba99efcf', 'measured_value', 'Measured Value', 'The numeric value actually observed during the inspection, such as a weight or temperature. Entered for numeric characteristics together with the unit; compared with the limits to give the result, and exclusive with measured text. Records the factual quantitative observation before evaluation. Requires a compatible unit for dimensional characteristics. Supplies evidence used against configured acceptance criteria.', 12, NULL, NULL, FALSE, FALSE, FALSE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 40, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('4a5ceb1a-3c40-563b-b5d8-ea3d37ea5902', 'ca3370d1-6356-5045-a4b5-2511ba99efcf', 'measured_text', 'Measured Text', 'The categorical or textual observation made, such as a colour grade or appearance remark. Entered for characteristics that are not numeric; used in evaluation where a number does not apply, and exclusive with measured value. Records observations such as color, grade, appearance or classification. Used instead of measuredValue for categorical characteristics. Supplies structured qualitative evidence.', 10, 1000, NULL, FALSE, FALSE, FALSE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 50, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('92006a1c-7e99-5ecc-8129-fb0ea7a6ae15', 'ca3370d1-6356-5045-a4b5-2511ba99efcf', 'unit_of_measure', 'Unit Of Measure', 'The unit, such as kilograms or degrees Celsius, in which the numeric measured value is expressed. Chosen with a numeric value; used to compare against limits, convert between units and report consistently. Defines the dimensional interpretation of measuredValue. Must be compatible with the linked QualityPlanCharacteristic and QualityCharacteristic. Makes numeric observations semantically comparable.', 19, NULL, NULL, FALSE, FALSE, FALSE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 60, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('748666c4-eef7-58d1-861b-ff8f816b8faf', 'ca3370d1-6356-5045-a4b5-2511ba99efcf', 'lower_limit', 'Lower Limit', 'Snapshot of the lower acceptance boundary applicable when the measurement was evaluated. Preserves the criterion used to evaluate the historical observation. Audit, reproducibility and review. Normally copied from QualityPlanCharacteristic rather than independently defining a new requirement. Makes the evaluation auditable even if the plan later changes.', 12, NULL, NULL, FALSE, FALSE, FALSE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 70, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('0ae44493-b903-5795-a0be-72e668a9d4ee', 'ca3370d1-6356-5045-a4b5-2511ba99efcf', 'upper_limit', 'Upper Limit', 'Snapshot of the upper acceptance boundary applicable when the measurement was evaluated. Preserves the criterion used to evaluate the historical observation. Audit, reproducibility and review. Normally copied from QualityPlanCharacteristic rather than independently defining a new requirement. Makes the evaluation auditable even if the plan later changes.', 12, NULL, NULL, FALSE, FALSE, FALSE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 80, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('a2e6f007-b32e-5299-94f8-33f30fd6cdcd', 'ca3370d1-6356-5045-a4b5-2511ba99efcf', 'result', 'Result', 'The verdict on this measurement when compared with its governing acceptance criterion. Set when the value is evaluated; inspections use it to complete, raise nonconformances and feed quality analytics. The measured value is within its limits. The measured value is outside its limits. Within tolerance only under a stated condition. No verdict has been given yet because it was not compared with a criterion. States whether the individual observation satisfies the applicable requirement. Contributes evidence to QualityInspection.result but does not replace it. Supplies structured evidence for the overall inspection decision.', 1030, NULL, NULL, FALSE, FALSE, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 90, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('5b6fcc58-8bc3-5552-ab0c-d208910171b5', 'ca3370d1-6356-5045-a4b5-2511ba99efcf', 'measured_at', 'Measured At', 'The date and time at which the observation was actually taken. Captured with the measurement; supports sampling traceability, compliance checks and audit of when results were obtained. Establishes chronology of the measured fact. Distinct from QualityInspection.inspectionDate. Preserves temporal measurement evidence.', 16, NULL, NULL, FALSE, FALSE, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 100, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('c9106eda-9f7d-5393-9eaf-36fc44b84e99', 'ca3370d1-6356-5045-a4b5-2511ba99efcf', 'method', 'Method', 'The method or procedure used to obtain the observation, such as a named test standard or instrument routine. Entered by the inspector; lets others reproduce the test and lets laboratory audits confirm the right method was used. Identifies how the measurement or test was performed. Should align with the linked QualityPlanCharacteristic method where applicable. Establishes how evidence was produced.', 10, 500, NULL, FALSE, FALSE, FALSE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 110, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('deaaa501-d10d-5212-a970-fa1a1baa847c', 'ca3370d1-6356-5045-a4b5-2511ba99efcf', 'notes', 'Notes', 'Supporting context for this observation, such as sample condition or instrument remarks. Free text entered by the inspector; read during review and audit to explain unusual values. Captures anomalies or conditions not represented structurally. Complements measured values and result without replacing them. Provides supporting evidence.', 10, 2000, NULL, FALSE, FALSE, FALSE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 120, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('d3908e60-f27d-5325-99c2-f7717078f499', 'ca3370d1-6356-5045-a4b5-2511ba99efcf', 'quality_characteristic_id', 'Quality Characteristic', 'Reusable quality property observed by this measurement. Identifies the semantic property independently of a particular plan. Traceability, analytics, reuse, and audit. Should agree with the QualityCharacteristic reached through qualityPlanCharacteristic when both are populated. Provides reusable semantic context.', 19, NULL, NULL, FALSE, FALSE, FALSE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 130, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('2924786b-87a0-5147-b02d-ec2ef3c928ca', 'ca3370d1-6356-5045-a4b5-2511ba99efcf', 'quality_plan_characteristic_id', 'Quality Plan Characteristic', 'Plan-specific requirement used to interpret and evaluate this measurement. Identifies the exact configured characteristic, limits, method, unit, and requiredness governing the observation. Requirement traceability, acceptance evaluation, audit, and completion gating. Supplies authoritative evaluation context for the measurement.', 19, NULL, NULL, FALSE, FALSE, FALSE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 140, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('dc7e77be-fd0f-5b91-98e2-3633d948277b', 'ca3370d1-6356-5045-a4b5-2511ba99efcf', 'test_method_id', 'Test Method', 'Governed test procedure used to produce this observation. Identifies the authoritative reusable method applied during measurement. Reproducibility, compliance, laboratory audit, and analytics. Optional when no reusable controlled method applies. Must agree with the governing QualityPlanCharacteristic method configuration when that configuration requires a TestMethod.', 19, NULL, NULL, FALSE, FALSE, FALSE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 150, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('84217137-e9bc-52b9-9537-08c4b2599e85', 'ca3370d1-6356-5045-a4b5-2511ba99efcf', 'quality_inspection_id', 'Quality Inspection', 'Inspection during which the measurement was captured. Provides the governing inspection context. Quality traceability and aggregate evaluation. Parent inspection controls measurement lifecycle.', 19, NULL, NULL, FALSE, FALSE, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 160, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('861f3e9d-3c5e-541c-8eca-a3b0e1b9519e', 'ca3370d1-6356-5045-a4b5-2511ba99efcf', 'inspection_sample_id', 'Inspection Sample', 'Exact governed inspection sample from which this observation was produced when sample-specific testing applies. Preserves provenance from SamplingPlan and SamplingRule execution through selected material to the resulting observation. Sample-level traceability, laboratory chain of custody, acceptance sampling, audit, and reproducibility. A measurement references zero or one InspectionSample because non-sampled or population-level observations may not have a sample record. When populated, the sample must belong to the same QualityInspection and the measurement must satisfy the characteristic controls applicable to that sample.', 19, NULL, NULL, FALSE, FALSE, FALSE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 170, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('4358e764-1173-52f0-a2b2-90e9c6353a31', 'ca3370d1-6356-5045-a4b5-2511ba99efcf', 'quality_plan_id', 'Quality Plan', 'Quality plan under which the measurement was evaluated. Preserves the plan context for the observation. Audit, reporting, requirement traceability, and historical reconstruction. Identifies the governing plan when a direct plan relationship is needed for integration or historical evidence.', 19, NULL, NULL, FALSE, FALSE, FALSE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 180, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('ff4240dc-c727-5b73-b7e1-5853c0cf23e3', 'ca3370d1-6356-5045-a4b5-2511ba99efcf', 'certificate_of_analysis_id', 'Certificate Of Analysis', 'The CertificateOfAnalysis this QualityMeasurement belongs to.', 19, NULL, NULL, FALSE, FALSE, FALSE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 190, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
