INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('532ddbfb-1eeb-57f0-bc53-d48f5f41e9cf', '7129094f-6a92-567d-82ca-cfd9be683e5d', '84217137-e9bc-52b9-9537-08c4b2599e85', 'a0e97de9-979a-56f6-af50-deacd5e8ff17', 'Quality Inspection', 'Inspection during which the measurement was captured. Provides the governing inspection context. Quality traceability and aggregate evaluation. Parent inspection controls measurement lifecycle. Required — the record cannot be saved while this is empty.', 160, 160, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
