INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('6e8e9e53-f000-51d2-8dcd-806ca3d2b5a3', '7129094f-6a92-567d-82ca-cfd9be683e5d', '861f3e9d-3c5e-541c-8eca-a3b0e1b9519e', 'a0e97de9-979a-56f6-af50-deacd5e8ff17', 'Inspection Sample', 'Exact governed inspection sample from which this observation was produced when sample-specific testing applies. Preserves provenance from SamplingPlan and SamplingRule execution through selected material to the resulting observation. Sample-level traceability, laboratory chain of custody, acceptance sampling, audit, and reproducibility. A measurement references zero or one InspectionSample because non-sampled or population-level observations may not have a sample record. When populated, the sample must belong to the same QualityInspection and the measurement must satisfy the characteristic controls applicable to that sample.', 170, 170, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
