-- Nonconformance (bus_nonconformance)
-- --------------------------------------------------------------------------
INSERT INTO sys_window (sys_window_id, name, description, help, icon, window_type, is_sales_transaction, is_default, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('83f50e02-e943-5bbc-ad5b-2ed3d8c13ffe', 'Nonconformance', 'Maintain Nonconformance records', 'Create, find and maintain Nonconformance records. The list shows every Nonconformance you have access to — select a row to open it, or use New to add one. Each row is a single Nonconformance, described by 9 fields.

Id and Number are unique: no two Nonconformance records may share the same value, and a save that would duplicate one is rejected. Number, Severity, Status, Description and Detected At must be filled in before the record can be saved.

Corrective Action, Corrective Action Verification and Return Disposition refer back to Nonconformance, so what you change here can affect those records.

Every save starts as a Draft. The business rules and workflows attached to Nonconformance then run together in a single transaction: if all of them succeed the record becomes Final; if any of them fails, nothing they changed is kept — the record stays Draft and the reason is written onto it so you can fix the cause and retry. A Nonconformance with no rules or workflows attached is marked Final immediately.', 'table', 'M', FALSE, TRUE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_table (sys_table_id, table_name, name, description, icon, access_level, is_view, is_document, is_high_volume, is_changelog, sys_window_id, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('73b60cec-c62f-5ed9-902c-2ef9b60c5234', 'bus_nonconformance', 'Nonconformance', 'Represents a controlled quality deviation and its investigation, containment, disposition and corrective-action lifecycle. Nonconformance captures the quality problem; QualityInspection provides test evidence; ReturnDisposition records controlled operational outcomes; SupplierReturn provides physical response; CorrectiveAction addresses recurrence; CorrectiveActionVerification proves effectiveness. Supplier quality, incoming inspection, returns, CAPA, compliance, audit, supplier performance and risk management. A quality issue may begin at receiving, inspection, customer/supplier return or external complaint. Operational, inventory and financial consequences remain separate business facts linked through traceable relationships. Inspection/receipt/return evidence → Nonconformance → containment → ReturnDisposition where applicable → SupplierReturn/InventoryMovement → CorrectiveAction → effectiveness verification → closure. Financial consequences remain separate through authorized credit/debit workflows. Open → under review → contained → corrective action → closed, with rejection where the issue is invalid. Changes to inspection, receipt, return, disposition, product, corrective action or verification evidence affecting an open issue trigger revalidation. Financial and inventory consequences are never inferred solely from Nonconformance status. Incoming inspection detects defective units. Nonconformance records the defect, affected receipt lines are contained, a return disposition sends the units to quarantine, a supplier return and inventory movement execute the physical response, CorrectiveAction addresses the root cause, and an effective verification supplies closure evidence.', 'table', 'A', FALSE, FALSE, FALSE, TRUE, '83f50e02-e943-5bbc-ad5b-2ed3d8c13ffe', 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_tab (sys_tab_id, sys_window_id, sys_table_id, name, help, tab_level, seq_no, is_single_row, has_tree, is_info_tab, is_translation_tab, is_read_only, is_insert_record, is_advanced_tab, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('a79d6644-2191-5199-9e2e-ab67f1a89e4d', '83f50e02-e943-5bbc-ad5b-2ed3d8c13ffe', '73b60cec-c62f-5ed9-902c-2ef9b60c5234', 'Nonconformance', 'Shows one Nonconformance at a time. Fields are grouped: General carries the identifying fields and Details carries the rest. 5 fields marked with a red asterisk (*) must have a value before Save will accept the record. Any field showing a ? beside its label has help of its own; click it for the rules that apply there.', 0, 10, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('00c07913-7eb1-5b75-8684-d643c51b2126', '73b60cec-c62f-5ed9-902c-2ef9b60c5234', 'id', 'Id', 'The identity of the nonconformance. Generated on recording; corrective actions and verifications refer to it. Identifies one quality deviation independently of its inspection, product, receipt, return or corrective action. Root identity for issue lifecycle.', 13, NULL, NULL, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, FALSE, FALSE, TRUE, FALSE, 10, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('21388bd6-79d9-5f2b-8b21-0a6744bd8169', '73b60cec-c62f-5ed9-902c-2ef9b60c5234', 'number', 'Number', 'The unique reference by which the deviation is cited in reports and corrective actions. Identifies the issue for quality and supplier operations. Audit, reporting, CAPA and dispute handling. Human-recognizable issue reference.', 10, 100, NULL, FALSE, FALSE, TRUE, TRUE, TRUE, TRUE, FALSE, FALSE, TRUE, TRUE, 20, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('c56624bb-4315-5f97-98f4-1c8d173aae02', '73b60cec-c62f-5ed9-902c-2ef9b60c5234', 'severity', 'Severity', 'How serious the deviation is. Set by quality at review; drives containment and escalation. Minor deviation with little effect. Notable deviation needing correction. Serious deviation affecting product or customers. Dangerous or legally significant deviation needing immediate containment. Indicates impact and urgency. Determines response urgency.', 1013, NULL, NULL, FALSE, FALSE, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 30, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('132dead7-d70a-556a-8bbd-73d70ba8ae81', '73b60cec-c62f-5ed9-902c-2ef9b60c5234', 'status', 'Status', 'Shows how far the quality deviation has progressed through review, containment, corrective action and closure. Moved by quality staff as the investigation advances; closing requires corrective action, and rejection ends a report that was not valid. The deviation has been recorded and nobody has yet started to investigate it. Quality staff are assessing the deviation to confirm what happened, how serious it is and who owns it. Affected material has been isolated or held so that it cannot reach customers or production while the cause is addressed. Actions to remove the cause and prevent recurrence are being carried out and checked. The deviation was resolved and its corrective actions were verified as effective. A final state. Review found no real deviation, or a duplicate report, so no further action is taken. A final state. Indicates investigation, containment, corrective action and closure. Controls allowed responses and closure.', 1014, NULL, NULL, FALSE, FALSE, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 40, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('b86cb4c7-92e2-59dc-9672-90481c92672f', '73b60cec-c62f-5ed9-902c-2ef9b60c5234', 'description', 'Description', 'A full account of what went wrong, naming the requirement or expected result that was not met. Written by whoever raises the issue and refined during review; read in investigation, supplier communication and audit. States what requirement or expected result was not met. Provides issue evidence.', 10, 4000, NULL, FALSE, FALSE, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 50, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('9726b8a4-3afc-53be-888e-465065ff235d', '73b60cec-c62f-5ed9-902c-2ef9b60c5234', 'detected_at', 'Detected At', 'The date and time when the deviation was first noticed, which may precede the time it was entered. Entered when the issue is raised; containment and corrective action deadlines are measured from it in quality analytics. Establishes chronology for containment and corrective action. Anchors issue occurrence.', 16, NULL, NULL, FALSE, FALSE, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 60, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('d6b0d919-530c-5136-82f4-787358b90b65', '73b60cec-c62f-5ed9-902c-2ef9b60c5234', 'closed_at', 'Closed At', 'The date and time when the deviation was formally closed or rejected by quality. Set when the status becomes closed or rejected; left empty while the issue is open, and used to measure time to resolve. Establishes completion chronology. Required for closure.', 16, NULL, NULL, FALSE, FALSE, FALSE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 70, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('675fabb6-4063-5b02-a48e-80627b06de25', '73b60cec-c62f-5ed9-902c-2ef9b60c5234', 'inspection_id', 'Inspection', 'Inspection that detected or evidenced the deviation. Connects issue to objective quality evaluation. Investigation and audit. Provides detection evidence.', 19, NULL, NULL, FALSE, FALSE, FALSE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 80, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
