INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('7adc9474-e505-54a2-bb82-0f890e5dbe28', 'a79d6644-2191-5199-9e2e-ab67f1a89e4d', '9726b8a4-3afc-53be-888e-465065ff235d', 'a0e97de9-979a-56f6-af50-deacd5e8ff17', 'Detected At', 'The date and time when the deviation was first noticed, which may precede the time it was entered. Entered when the issue is raised; containment and corrective action deadlines are measured from it in quality analytics. Establishes chronology for containment and corrective action. Anchors issue occurrence. Required — the record cannot be saved while this is empty.', 60, 60, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('b32e2d04-ab6a-55e5-b199-48fdd2d5b549', 'a79d6644-2191-5199-9e2e-ab67f1a89e4d', 'd6b0d919-530c-5136-82f4-787358b90b65', 'a0e97de9-979a-56f6-af50-deacd5e8ff17', 'Closed At', 'The date and time when the deviation was formally closed or rejected by quality. Set when the status becomes closed or rejected; left empty while the issue is open, and used to measure time to resolve. Establishes completion chronology. Required for closure.', 70, 70, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('293ca2f4-2b96-5d7e-a930-e06413220bce', 'a79d6644-2191-5199-9e2e-ab67f1a89e4d', '675fabb6-4063-5b02-a48e-80627b06de25', 'a0e97de9-979a-56f6-af50-deacd5e8ff17', 'Inspection', 'Inspection that detected or evidenced the deviation. Connects issue to objective quality evaluation. Investigation and audit. Provides detection evidence.', 80, 80, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('d89232c1-90be-5f31-bfd9-65d86ad04cb3', 'a79d6644-2191-5199-9e2e-ab67f1a89e4d', '38721ab6-9f4f-511a-a1fa-39116f0d1ed3', 'a0e97de9-979a-56f6-af50-deacd5e8ff17', 'Owner', 'Party accountable for issue management. Identifies responsible quality owner or organizational party. Escalation, CAPA and audit. Owns investigation and closure.', 90, 90, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
