-- --------------------------------------------------------------------------
-- Corrective Action (bus_corrective_action)
-- --------------------------------------------------------------------------
INSERT INTO sys_window (sys_window_id, name, description, help, icon, window_type, is_sales_transaction, is_default, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('0b2fd043-d984-5a50-b0cf-ce391062dd94', 'Corrective Action', 'Maintain Corrective Action records', 'Create, find and maintain Corrective Action records. The list shows every Corrective Action you have access to — select a row to open it, or use New to add one. Each row is a single Corrective Action, described by 9 fields.

Id and Action Number are unique: no two Corrective Action records may share the same value, and a save that would duplicate one is rejected. Action Number, Action Type, Description and Status must be filled in before the record can be saved.

Every Corrective Action points at Nonconformance. Choose the linked record from the lookup on those fields rather than typing an identifier. Corrective Action Verification refers back to Corrective Action, so what you change here can affect that record.

Every save starts as a Draft. The business rules and workflows attached to Corrective Action then run together in a single transaction: if all of them succeed the record becomes Final; if any of them fails, nothing they changed is kept — the record stays Draft and the reason is written onto it so you can fix the cause and retry. A Corrective Action with no rules or workflows attached is marked Final immediately.', 'table', 'M', FALSE, TRUE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_table (sys_table_id, table_name, name, description, icon, access_level, is_view, is_document, is_high_volume, is_changelog, sys_window_id, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('fc395ad0-293c-5b8c-a24f-4c05bdb3580f', 'bus_corrective_action', 'Corrective Action', 'Represents a controlled quality action from assignment through implementation and independent effectiveness verification. Nonconformance records the problem; CorrectiveAction records what is done to contain, correct or prevent it; CorrectiveActionVerification records whether the action worked. CAPA, supplier quality, compliance, audit, recurrence prevention and quality improvement. The action connects Nonconformance with responsible Party and one or more CorrectiveActionVerification records. Physical and financial consequences remain represented by their own transactions. Open → assigned → in progress → verification → completed, with cancellation and reopening paths. Nonconformance → action definition → assignment → implementation → verification → effective completion → Nonconformance closure when all required evidence is satisfied. Ineffective verification returns the action to controlled follow-up. Changes to the originating Nonconformance or quality evidence affecting the action trigger revalidation of scope and verification criteria. Verification results may reopen or create additional action work; historical records remain immutable. A supplier defect causes a corrective action to change packaging controls. The action is implemented, a verification evaluates subsequent lots, and only an EFFECTIVE verification permits completion when policy requires effectiveness evidence.', 'table', 'A', FALSE, FALSE, FALSE, TRUE, '0b2fd043-d984-5a50-b0cf-ce391062dd94', 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_tab (sys_tab_id, sys_window_id, sys_table_id, name, help, tab_level, seq_no, is_single_row, has_tree, is_info_tab, is_translation_tab, is_read_only, is_insert_record, is_advanced_tab, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('04be8f13-d5cf-5742-a89b-642a64fd5dfd', '0b2fd043-d984-5a50-b0cf-ce391062dd94', 'fc395ad0-293c-5b8c-a24f-4c05bdb3580f', 'Corrective Action', 'Shows one Corrective Action at a time. Fields are grouped: General carries the identifying fields and Details carries the rest. 4 fields marked with a red asterisk (*) must have a value before Save will accept the record. Nonconformance is a lookup — search the linked records instead of entering an identifier by hand. Any field showing a ? beside its label has help of its own; click it for the rules that apply there.', 0, 10, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('066a96a8-5e4e-5103-81c7-8caa481dd403', 'fc395ad0-293c-5b8c-a24f-4c05bdb3580f', 'id', 'Id', 'The permanent system identity of one corrective or preventive action. Generated on creation; verifications, nonconformances and audits refer to the action through it. Identifies one controlled quality action independently of its issue, owner, implementation evidence or verification. Distinct from Nonconformance and CorrectiveActionVerification identities. Stable reference through assignment, execution, verification and closure.', 13, NULL, NULL, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, FALSE, FALSE, TRUE, FALSE, 10, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('fd5a9be2-1456-54e0-8358-066b4b3ec4f2', 'fc395ad0-293c-5b8c-a24f-4c05bdb3580f', 'action_number', 'Action Number', 'The unique reference number by which people refer to the action in CAPA meetings and reports. Assigned when the action is raised; quoted in supplier communication, tracking dashboards and integrations. Identifies the action for quality teams, responsible parties and auditors. Distinct from the originating nonconformance number and verification number. Correlates action work across its lifecycle.', 10, 100, NULL, FALSE, FALSE, TRUE, TRUE, TRUE, TRUE, FALSE, FALSE, TRUE, TRUE, 20, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('0eb61bca-9881-5423-8603-279c3afb9880', 'fc395ad0-293c-5b8c-a24f-4c05bdb3580f', 'action_type', 'Action Type', 'The purpose of the action: containing a problem, fixing the item, removing its cause, or preventing recurrence elsewhere. Chosen by the quality owner; decides what evidence is expected, who reviews it and how effectiveness is judged. Immediate action to stop the problem spreading, such as quarantining stock. Fixing the specific nonconforming item or condition. Removing the root cause so the problem does not recur. Action to prevent a similar problem elsewhere before it happens. Distinguishes immediate containment, correction of an existing condition, root-cause corrective action, and preventive action. Containment/disposition can control immediate risk while corrective/preventive actions address causes and recurrence. Determines the intended outcome that verification must assess.', 1003, NULL, NULL, FALSE, FALSE, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 30, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('becf4463-1b7a-543d-a900-51f7fa015ddc', 'fc395ad0-293c-5b8c-a24f-4c05bdb3580f', 'description', 'Description', 'Detailed statement of what the action will accomplish. Defines scope, intended outcome and work required to address the quality issue. Assignment, execution, audit and effectiveness assessment. Must remain traceable to the associated Nonconformance or approved quality objective. Defines the implementation target for verification.', 10, 4000, NULL, FALSE, FALSE, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 40, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('2d830b7a-54ae-59ef-9aad-17a7ab28ebd0', 'fc395ad0-293c-5b8c-a24f-4c05bdb3580f', 'status', 'Status', 'Where the action stands from being raised, assigned and carried out to verification and closure. Moved by the action owner and quality reviewer; completion needs the completed date and, where required, an effective verification. Raised but not yet assigned. Given to an owner, who has not started. Being carried out by the owner, with implementation not yet finished. Done and waiting for an effectiveness check. Done and, where required, verified effective. A final state. Withdrawn and not carried out. A final state. Indicates whether work is pending, assigned, underway, awaiting effectiveness evidence, completed or cancelled. COMPLETED does not itself prove effectiveness; CorrectiveActionVerification supplies that evidence. VERIFICATION gates final completion when effectiveness verification is required.', 1004, NULL, NULL, FALSE, FALSE, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 50, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('83f12a44-5ad5-5696-bb56-a58c2750e463', 'fc395ad0-293c-5b8c-a24f-4c05bdb3580f', 'due_date', 'Due Date', 'The date by which the action should be implemented. Agreed when the action is assigned; drives reminders and escalation, and overdue counts in quality governance reports. Defines when the responsible party is expected to complete implementation. Distinct from completedDate and verificationDate. Supports overdue detection and escalation.', 15, NULL, NULL, FALSE, FALSE, FALSE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 60, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('8be338bf-16f2-5baf-8f48-bce1266ab70d', 'fc395ad0-293c-5b8c-a24f-4c05bdb3580f', 'completed_date', 'Completed Date', 'The date implementation was formally finished, which may differ from the verification date. Recorded when the action completes and required then; CAPA metrics measure time to complete against the due date. Records when the action work was declared complete, subject to any required effectiveness verification. Does not replace verification evidence where effectiveness is required. Required when status is COMPLETED.', 15, NULL, NULL, FALSE, FALSE, FALSE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 70, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('d1ba37f3-a76d-5dba-bf83-54ede8d70d7a', 'fc395ad0-293c-5b8c-a24f-4c05bdb3580f', 'nonconformance_id', 'Nonconformance', 'Quality issue that caused or requires this action. Connects the action to the deviation and its containment, disposition and closure requirements. CAPA traceability, root-cause analysis and audit. Supplies the problem context the action is intended to address.', 19, NULL, NULL, FALSE, FALSE, FALSE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 80, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('fa6e8745-0836-5acb-bcaf-a52d13187b55', 'fc395ad0-293c-5b8c-a24f-4c05bdb3580f', 'owner_id', 'Owner', 'Party accountable for implementing the action. Identifies the responsible person or organization for execution. Assignment, escalation and accountability. Owns implementation evidence and completion proposal.', 19, NULL, NULL, FALSE, FALSE, FALSE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 90, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
UPDATE sys_column SET ref_table_name = 'bus_party' WHERE sys_column_id = 'fa6e8745-0836-5acb-bcaf-a52d13187b55';
