VALUES ('2b71e3a5-e92b-51ea-a671-3c75b2e41124', '04be8f13-d5cf-5742-a89b-642a64fd5dfd', '83f12a44-5ad5-5696-bb56-a58c2750e463', 'a0e97de9-979a-56f6-af50-deacd5e8ff17', 'Due Date', 'The date by which the action should be implemented. Agreed when the action is assigned; drives reminders and escalation, and overdue counts in quality governance reports. Defines when the responsible party is expected to complete implementation. Distinct from completedDate and verificationDate. Supports overdue detection and escalation.', 60, 60, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
