INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('b3160aa8-4488-5044-81c5-1e374adf65bb', '04be8f13-d5cf-5742-a89b-642a64fd5dfd', '8be338bf-16f2-5baf-8f48-bce1266ab70d', 'a0e97de9-979a-56f6-af50-deacd5e8ff17', 'Completed Date', 'The date implementation was formally finished, which may differ from the verification date. Recorded when the action completes and required then; CAPA metrics measure time to complete against the due date. Records when the action work was declared complete, subject to any required effectiveness verification. Does not replace verification evidence where effectiveness is required. Required when status is COMPLETED.', 70, 70, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
