INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('143851d7-1313-59b9-85e3-05d47d55689c', '04be8f13-d5cf-5742-a89b-642a64fd5dfd', 'd1ba37f3-a76d-5dba-bf83-54ede8d70d7a', 'a0e97de9-979a-56f6-af50-deacd5e8ff17', 'Nonconformance', 'Quality issue that caused or requires this action. Connects the action to the deviation and its containment, disposition and closure requirements. CAPA traceability, root-cause analysis and audit. Supplies the problem context the action is intended to address.', 80, 80, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
