-- --------------------------------------------------------------------------
-- Corrective Action Verification (bus_corrective_action_verification)
-- --------------------------------------------------------------------------
INSERT INTO sys_window (sys_window_id, name, description, help, icon, window_type, is_sales_transaction, is_default, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('0ad9e0b9-c4a3-565f-be34-6a1e9866adfe', 'Corrective Action Verification', 'Maintain Corrective Action Verification records', 'Create, find and maintain Corrective Action Verification records. The list shows every Corrective Action Verification you have access to — select a row to open it, or use New to add one. Each row is a single Corrective Action Verification, described by 9 fields.

Id and Verification Number are unique: no two Corrective Action Verification records may share the same value, and a save that would duplicate one is rejected. Verification Number, Verification Date, Result, Status, Findings, Verified By and Corrective Action must be filled in before the record can be saved.

Every Corrective Action Verification points at Nonconformance and Corrective Action. Choose the linked record from the lookup on those fields rather than typing an identifier.

Every save starts as a Draft. The business rules and workflows attached to Corrective Action Verification then run together in a single transaction: if all of them succeed the record becomes Final; if any of them fails, nothing they changed is kept — the record stays Draft and the reason is written onto it so you can fix the cause and retry. A Corrective Action Verification with no rules or workflows attached is marked Final immediately.', 'file-text', 'M', FALSE, TRUE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_table (sys_table_id, table_name, name, description, icon, access_level, is_view, is_document, is_high_volume, is_changelog, sys_window_id, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('c88e3563-d132-5b22-9599-8f6c6b91f6c9', 'bus_corrective_action_verification', 'Corrective Action Verification', 'Provides independent auditable evidence that a corrective or preventive action achieved its intended result. CorrectiveAction records what was done; CorrectiveActionVerification records whether it worked; Nonconformance records the original quality problem. CAPA supplier quality compliance audit recurrence prevention and issue closure. Verification closes the evidence loop between Nonconformance and CorrectiveAction without conflating implementation with effectiveness. Nonconformance → CorrectiveAction → implementation → effectiveness verification → effective closure or ineffective/reopened action → Nonconformance closure when all required evidence is satisfied. Open → in progress → completed, with reopened or cancelled paths. Ineffective verification reopens or creates additional CorrectiveAction work according to policy; it must not silently close the underlying Nonconformance. A supplier defect causes a corrective action requiring a packaging-process change. After implementation, verification evaluates subsequent lots, records EFFECTIVE, and provides evidence needed to complete the action and eventually close the nonconformance.', 'file-text', 'A', FALSE, FALSE, FALSE, TRUE, '0ad9e0b9-c4a3-565f-be34-6a1e9866adfe', 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_tab (sys_tab_id, sys_window_id, sys_table_id, name, help, tab_level, seq_no, is_single_row, has_tree, is_info_tab, is_translation_tab, is_read_only, is_insert_record, is_advanced_tab, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('32ba71ef-a318-56c2-896b-78212d42a9c9', '0ad9e0b9-c4a3-565f-be34-6a1e9866adfe', 'c88e3563-d132-5b22-9599-8f6c6b91f6c9', 'Corrective Action Verification', 'Shows one Corrective Action Verification at a time. Fields are grouped: General carries the identifying fields and Details carries the rest. 7 fields marked with a red asterisk (*) must have a value before Save will accept the record. Nonconformance and Corrective Action are lookups — search the linked records instead of entering an identifier by hand. Any field showing a ? beside its label has help of its own; click it for the rules that apply there.', 0, 10, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('b522e7b5-89a6-53bf-9704-c91331e42f60', 'c88e3563-d132-5b22-9599-8f6c6b91f6c9', 'id', 'Id', 'The identity of the verification record. Identifies one independent verification event assessing an implemented corrective or preventive action. Quality assurance CAPA audit supplier performance and closure evidence. Distinct from CorrectiveAction and Nonconformance identities. Provides traceable evidence for a completion decision.', 13, NULL, NULL, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, FALSE, FALSE, TRUE, FALSE, 10, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('1996c8f2-f62d-5f02-a9fd-066beb0517f0', 'c88e3563-d132-5b22-9599-8f6c6b91f6c9', 'verification_number', 'Verification Number', 'The unique reference number that quality staff and suppliers quote for this effectiveness check. Assigned when the verification is raised; used in approvals, audit trails and supplier correspondence. Identifies the verification event for quality operations and audit. Distinct from actionNumber and nonconformance number. Correlates verification evidence throughout closure.', 10, 100, NULL, FALSE, FALSE, TRUE, TRUE, TRUE, TRUE, FALSE, FALSE, TRUE, TRUE, 20, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('4dbec981-aaa4-5ce6-b77f-f118b2892a57', 'c88e3563-d132-5b22-9599-8f6c6b91f6c9', 'verification_date', 'Verification Date', 'Date and time effectiveness verification was performed. Establishes when evidence was evaluated against the intended outcome. Audit SLA quality reporting and closure chronology. Anchors the verification event.', 16, NULL, NULL, FALSE, FALSE, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 30, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('a8cab20c-d7d4-50bb-a131-aa3c2f491b4d', 'c88e3563-d132-5b22-9599-8f6c6b91f6c9', 'result', 'Result', 'The verifier''s conclusion on whether the action achieved its intended result. Recorded when verification completes; an effective result can support closing the action, while other results force further work or an exception. The action achieved its intended result and the problem has not recurred. The action helped but did not fully remove the problem; further action is needed. The action did not work and the problem persists or has returned. Effectiveness cannot be established, for example because there is not yet enough evidence. States whether the action achieved its intended quality outcome. Does not rewrite original Nonconformance or CorrectiveAction evidence. Determines whether action may be completed or must be reopened.', 1005, NULL, NULL, FALSE, FALSE, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 40, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('135c57d5-09c0-5bbc-8179-a301cbd60978', 'c88e3563-d132-5b22-9599-8f6c6b91f6c9', 'status', 'Status', 'Where the verification is, from being raised through the check to completion, reopening or cancellation. Moved by the independent verifier; a verification can only complete once a result and findings are recorded. Raised but not started. The verification is being carried out. Finished with a result and findings recorded. A final state. Reopened because new evidence or a recurrence needs further verification. Withdrawn and not carried out. A final state. Separates preparation evaluation completion and follow-up. COMPLETED records final verification evidence; REOPENED signals additional action is required.', 1006, NULL, NULL, FALSE, FALSE, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 50, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('99fe1e0f-8632-55ec-a8ad-a21917222091', 'c88e3563-d132-5b22-9599-8f6c6b91f6c9', 'findings', 'Findings', 'Evidence and observations supporting the verification result. Explains what was checked and why the result was reached. Audit quality review supplier improvement and recurrence analysis. Supports effectiveness decision.', 10, 4000, NULL, FALSE, FALSE, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 60, 'U', TRUE, 'system', 'system', NOW(), NOW())
