-- --------------------------------------------------------------------------
-- Certificate Of Analysis (bus_certificate_of_analysis)
-- --------------------------------------------------------------------------
INSERT INTO sys_window (sys_window_id, name, description, help, icon, window_type, is_sales_transaction, is_default, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('e0ebc497-91da-5163-9c3b-f937c5a035f9', 'Certificate Of Analysis', 'Maintain Certificate Of Analysis records', 'Create, find and maintain Certificate Of Analysis records. The list shows every Certificate Of Analysis you have access to — select a row to open it, or use New to add one. Each row is a single Certificate Of Analysis, described by 4 fields.

Id and Certificate Number are unique: no two Certificate Of Analysis records may share the same value, and a save that would duplicate one is rejected. Certificate Number and Status must be filled in before the record can be saved.

Quality Measurement refers back to Certificate Of Analysis, so what you change here can affect that record.

Every save starts as a Draft. The business rules and workflows attached to Certificate Of Analysis then run together in a single transaction: if all of them succeed the record becomes Final; if any of them fails, nothing they changed is kept — the record stays Draft and the reason is written onto it so you can fix the cause and retry. A Certificate Of Analysis with no rules or workflows attached is marked Final immediately.', 'table', 'M', FALSE, TRUE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_table (sys_table_id, table_name, name, description, icon, access_level, is_view, is_document, is_high_volume, is_changelog, sys_window_id, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('7b6b19a0-83da-59f3-90c2-ea8b2030adbd', 'bus_certificate_of_analysis', 'Certificate Of Analysis', 'Controlled certificate presenting quality evidence for governed material. CertificateOfAnalysis is a released representation of underlying evidence, not a substitute for QualityInspection or QualityMeasurement. Supplier quality, customer documentation, regulated release, shipments, receipts, compliance, audit, and integrations. Inspections and measurements supply evidence; Product and receipt/shipment provide material context. Draft → approved → issued → superseded/void under controlled document history. Changes to open source evidence invalidate draft/approved certificates for revalidation; issued certificates retain historical source references and are corrected by supersession.', 'table', 'A', FALSE, FALSE, FALSE, TRUE, 'e0ebc497-91da-5163-9c3b-f937c5a035f9', 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_tab (sys_tab_id, sys_window_id, sys_table_id, name, help, tab_level, seq_no, is_single_row, has_tree, is_info_tab, is_translation_tab, is_read_only, is_insert_record, is_advanced_tab, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('cc7a203a-b12c-5c6c-945a-f607e8beb930', 'e0ebc497-91da-5163-9c3b-f937c5a035f9', '7b6b19a0-83da-59f3-90c2-ea8b2030adbd', 'Certificate Of Analysis', 'Shows one Certificate Of Analysis at a time. Fields are grouped: General carries the identifying fields and Details carries the rest. 2 fields marked with a red asterisk (*) must have a value before Save will accept the record. Any field showing a ? beside its label has help of its own; click it for the rules that apply there.', 0, 10, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('a01a7947-613e-538c-93d6-c685d36a0ae8', '7b6b19a0-83da-59f3-90c2-ea8b2030adbd', 'id', 'Id', 'The permanent system identity of one certificate of analysis. Generated on creation; shipments, receipts and customer exchanges refer to the certificate through it, whatever its printed number. Identifies one issued quality certificate independently of its document number. Links certificate representation to source quality evidence.', 13, NULL, NULL, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, FALSE, FALSE, TRUE, FALSE, 10, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('59b8fed9-fd4c-51e9-96ad-0a42c7ca6cbc', '7b6b19a0-83da-59f3-90c2-ea8b2030adbd', 'certificate_number', 'Certificate Number', 'The unique number printed on the certificate, which customers and auditors quote when asking for it. Assigned by quality when the certificate is drafted; used for search, document exchange and audit, and never reused. Controlled number used to identify the issued certificate. Distinct from inspection and shipment numbers.', 10, 120, NULL, FALSE, FALSE, TRUE, TRUE, TRUE, TRUE, FALSE, FALSE, TRUE, TRUE, 20, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('01902f1b-1f8d-5eea-8fa6-af1790b3dea6', '7b6b19a0-83da-59f3-90c2-ea8b2030adbd', 'issued_at', 'Issued At', 'The date and time the certificate was released to its recipient, such as a customer or receiving site. Recorded when the status becomes issued and required by then; customers and auditors rely on it as the release date. Establishes when the quality statement became externally or operationally effective. Required once status is ISSUED.', 16, NULL, NULL, FALSE, FALSE, FALSE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 30, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('47103ad4-0841-5a71-a190-b828390556c8', '7b6b19a0-83da-59f3-90c2-ea8b2030adbd', 'status', 'Status', 'Where the certificate stands in controlled release, from drafting to issue and eventual replacement or withdrawal. Moved by quality staff; only issued certificates are sent to customers, and corrections create a replacement rather than an edit. Being prepared from the inspection results; not yet approved. Approved by quality but not yet released to the customer. Released to the recipient; it now stands as evidence. Replaced by a corrected certificate; kept for history. A final state. Withdrawn because it was wrong or issued in error; kept for history. A final state. Controls whether the certificate is preparatory, approved, issued, replaced, or invalidated. Status does not alter underlying measurements.', 1002, NULL, NULL, FALSE, FALSE, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 40, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
